uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// User Parameters (Preserved)
uniform float u_speed;
uniform float u_fov;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_complexity; 
uniform float u_viscosity;
uniform float u_paper_texture;
uniform float u_metallic_shine;
uniform float u_bloom_brightness;
uniform float u_paint_thickness;
uniform float u_creaminess;
uniform float u_melting;
uniform float u_berry_intensity;

// New Parameter for Wave Height
uniform float u_wave_height;

out vec4 fragColor;

// --- UTILS ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Multi-tone Palette: Dark Chocolate, Strawberry Pink, and Vanilla Cream
vec3 getIceCreamPalette(float t, float mask) {
    vec3 blackChoc   = vec3(0.02, 0.005, 0.01); // Deepest Black/Berry Brown
    vec3 strawberry  = vec3(1.0, 0.3, 0.55) * u_berry_intensity; // Vibrant Pink
    vec3 cream       = vec3(1.0, 0.96, 0.94);    // Vanilla/Strawberry Cream

    // Create a marbled effect
    float selector = sin(t * 2.0 + mask * 5.0) * 0.5 + 0.5;

    // Mix Dark Chocolate with Strawberry Pink
    vec3 finalCol = mix(blackChoc, strawberry, smoothstep(0.2, 0.6, selector));

    // Swirl in the Cream
    finalCol = mix(finalCol, cream, smoothstep(0.7, 0.95, selector) * u_creaminess);

    return finalCol;
}

void main() {
    // 1. Coordinate Setup
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv_orig = uv;

    // Zoom control
    uv *= (3.0 - u_fov); 

    float t = iTime * u_speed * 0.15;

    // 2. Liquid Distortion (The "Ice Cream Swirl")
    vec2 p = uv;
    float flow = 0.0;

    // Melt effect: Slight downward drag
    p.y -= t * u_melting * 0.2;

    // Wave Height influence: scales the amplitude of the fractal distortion
    float waveAmp = u_wave_height;

    for(float i = 1.0; i <= u_complexity; i++) {
        // Distort for viscous ribbon look, multiplied by Wave Height
        p.x += (waveAmp / i) * sin(i * 2.2 * p.y + t + u_viscosity * 5.0);
        p.y += (waveAmp / i) * cos(i * 2.2 * p.x + t + u_viscosity * 5.0);

        p *= rot(u_camera_dist * 0.05);

        flow += length(p - uv);
    }

    // 3. Distance Fields for the Creamy folds
    float d = length(sin(p * 0.8)) - 0.5;

    // Soft blend for "Thick" feel
    float mask = smoothstep(1.0 + u_paint_thickness * 0.4, -0.2, d);

    // Add internal depth glow
    float glow = exp(-abs(d) * 3.0) * u_glow_intensity;

    // 4. Color Compositing
    vec3 baseCol = getIceCreamPalette(flow * 0.1 + t * 0.2, mask);

    // Dark base background logic
    vec3 finalCol = mix(vec3(0.01, 0.002, 0.005), baseCol, clamp(mask + glow, 0.0, 1.0));

    // 5. Glossy Reflections (The moisture of melting ice cream)
    // Normals are influenced by the flow height
    vec3 n = normalize(vec3(dFdx(flow), dFdy(flow), 0.2 / (0.1 + u_wave_height))); 
    vec3 lightDir = normalize(vec3(sin(t * 0.5), 1.0, 2.0));

    // Specular highlight (Satin finish)
    float spec = pow(max(0.0, dot(n, lightDir)), 8.0) * u_metallic_shine;

    // Bloom tinted by the surface color
    vec3 highlight = mix(baseCol, vec3(1.0), 0.5);
    finalCol += spec * highlight * u_bloom_brightness;

    // 6. Surface Texture (Vanilla bean specks or berry seeds)
    float grain = noise(gl_FragCoord.xy * 0.2);
    if (u_paper_texture > 0.0) {
        // Darker specks like seeds
        finalCol *= 1.0 - (grain * u_paper_texture * (0.5 + 0.5 * u_creaminess));
    }

    // 7. Post Processing
    float vignette = smoothstep(1.2, 0.3, length(uv_orig));
    finalCol *= vignette;

    // Richer contrast
    finalCol = pow(finalCol, vec3(0.95)); 
    finalCol = smoothstep(-0.02, 1.05, finalCol);

    fragColor = vec4(finalCol, 1.0);
}
